--accent);vertical-align:middle;margin-right:4px}\n.k.t::before{border-top:2px dashed var(--accent-alt)}\n.stats{display:flex;gap:8px}\n.stats>div{flex:1;display:flex;flex-direction:column;align-items:center;padding:4px;border-radius:8px;background:var(--soft);min-width:0}\n.sl{font-size:10px;color:var(--muted)}\n.stats b{font-size:15px;font-variant-numeric:tabular-nums}\n.sec{display:flex;flex-direction:column;gap:6px;min-width:0}\n.sh{font-size:12px;font-weight:700;color:var(--muted)}\n\n.plist{display:flex;flex-direction:column;gap:8px;min-width:0}\n.prow{display:flex;flex-direction:column;gap:3px;min-width:0;padding:6px 8px;border-radius:8px;background:var(--soft)}\n.ph{display:flex;align-items:center;gap:6px;min-width:0}\n.pn{font-weight:700;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pv{font-weight:800;font-size:16px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.tag{font-size:10px;padding:0 5px;border-radius:999px;border:1px solid var(--line);color:var(--muted);white-space:nowrap;flex:0 0 auto}\n.tag.lo{border-color:var(--accent-alt);color:var(--ink)}\n.tag.hi{border-color:var(--accent);color:var(--ink)}\n.pt{display:flex;align-items:center;gap:8px;min-width:0}\n.track{position:relative;flex:1;height:8px;border-radius:99px;background:var(--panel-paper);box-shadow:inset 0 0 0 1px var(--line);min-width:0}\n.fill{position:absolute;left:0;top:0;bottom:0;width:var(--w,0%);border-radius:99px;background:var(--accent)}\n.tick{position:absolute;top:-3px;bottom:-3px;left:var(--l,0%);width:2px;margin-left:-1px;background:var(--accent-alt);border-radius:1px}\n.pm{font-size:11px;color:var(--muted);overflow-wrap:anywhere}\n.list{display:flex;flex-direction:column;gap:4px;min-width:0}\n.rrow{display:grid;grid-template-columns:1fr auto auto auto;align-items:center;gap:8px;width:100%;min-width:0;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;text-align:left;cursor:pointer}\n.rd{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.rt{font-weight:800;font-size:15px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.rg{font-size:11px;color:var(--muted);white-space:nowrap}\n.dlist{display:flex;flex-direction:column;gap:2px}\n.drow{display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid var(--line);min-width:0;flex-wrap:wrap}\n.dn2{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dv{font-size:15px;font-variant-numeric:tabular-nums}\n.note{font-size:12px;color:var(--muted);padding:6px 8px;border-radius:8px;background:var(--soft);overflow-wrap:anywhere}\n.fgrid{display:grid;grid-template-columns:1fr;gap:8px;align-content:start}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fl{font-size:12px;font-weight:600}\n.fl em{font-style:normal;font-weight:400;color:var(--muted)}\n.in{width:100%;min-width:0;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:14px}\n.in:focus{outline:2px solid var(--accent);outline-offset:0}\n.srow{display:flex;flex-direction:column;gap:5px;padding:6px;border:1px solid var(--line);border-radius:8px;min-width:0}\n.srow2{display:flex;gap:6px;align-items:center;min-width:0}\n.srow2 .in{flex:1 1 0}\n.settings .body{gap:8px}\n.settings .btn{align-self:flex-start}\n.card[data-size=\"3x3\"]{padding:8px}\n.card[data-size=\"3x3\"] .big{font-size:30px}\n.card[data-size=\"3x3\"] .sumrow{flex-wrap:nowrap;gap:8px}\n.card[data-size=\"3x3\"] .btn{height:28px;padding:0 8px;font-size:12px}\n.card[data-size=\"3x3\"] .btn.mini{height:22px}\n.card[data-size=\"3x3\"] .rrow{grid-template-columns:1fr auto auto;gap:6px;padding:5px 6px}\n.card[data-size=\"3x3\"] .ov{gap:4px}\n.card[data-size=\"3x3\"] .view{gap:5px}\n.card[data-size=\"6x3\"] .ov{flex-direction:row;align-items:stretch;gap:12px}\n.card[data-size=\"6x3\"] 