var SVGNS='http://www.w3.org/2000/svg';
var SZ={'3x3':{n:5,cw:170,ch:40,mini:true},'6x3':{n:6,cw:230,ch:84},'3x6':{n:6,cw:170,ch:120},'6x6':{n:10,cw:372,ch:120}};
function num(v){if(v===null||v===undefined||v==='')return null;var x=Number(v);return Number.isFinite(x)?x:null}
function fmt(x){if(x===null||x===undefined||!Number.isFinite(x))return '—';return String(Math.round(x*10)/10)}
function rd(x){return Math.round(x*10)/10}
function sgn(x){var r=rd(x);return (r>0?'+':'')+r}
function shortDate(d){return typeof d==='string'&&d.length>=10?d.slice(5,7)+'/'+d.slice(8,10):String(d||'')}
function norm(s){
  s=s&&typeof s==='object'?s:{};
  var st=s.settings&&typeof s.settings==='object'?s.settings:{};
  return Object.assign({},s,{
    records:Array.isArray(s.records)?s.records.filter(function(r){return r&&r.id}):[],
    settings:Object.assign({},st,{target:num(st.target),parts:Array.isArray(st.parts)?st.parts.filter(function(p){return p&&p.id}):[]})
  });
}
function sortedRecs(n){
  return n.records.map(function(r,i){return {r:r,i:i}}).sort(function(a,b){
    var x=String(a.r.date||''),y=String(b.r.date||'');
    return x<y?-1:x>y?1:a.i-b.i;
  }).map(function(o){return o.r});
}
function sv(tag,attrs){
  var e=document.createElementNS(SVGNS,tag);
  for(var k in (attrs||{})){var v=attrs[k];if(v!==null&&v!==undefined)e.setAttribute(k,String(v))}
  for(var i=2;i<arguments.length;i++){var c=arguments[i];if(c!==null&&c!==undefined)e.appendChild(typeof c==='string'?document.createTextNode(c):c)}
  return e;
}
function lineChart(pts,target,W,H,mini){
  var padT=mini?6:16,padB=mini?6:16,padL=14,padR=14,N=pts.length;
  var vals=pts.map(function(p){return p.v});
  if(target!==null&&target!==undefined)vals.push(target);
  var lo=Math.min.apply(null,vals),hi=Math.max.apply(null,vals);
  if(hi-lo<1){hi=lo+10;lo=lo-10}
  var pad=(hi-lo)*0.18;lo-=pad;hi+=pad;
  var X=function(i){return N===1?W/2:padL+(W-padL-padR)*i/(N-1)};
  var Y=function(v){return padT+(H-padT-padB)*(1-(v-lo)/(hi-lo))};
  var base=H-padB+2;
  var svg=sv('svg',{viewBox:'0 0 '+W+' '+H,class:'chart',role:'img','aria-label':'总分变化折线图',preserveAspectRatio:'xMidYMid meet'});
  svg.appendChild(sv('line',{class:'ax',x1:padL-6,x2:W-padR+6,y1:base,y2:base}));
  if(target!==null&&target!==undefined)svg.appendChild(sv('line',{class:'tg',x1:padL-6,x2:W-padR+6,y1:Y(target).toFixed(1),y2:Y(target).toFixed(1)}));
  var path=pts.map(function(p,i){return (i?'L':'M')+X(i).toFixed(1)+' '+Y(p.v).toFixed(1)}).join(' ');
  if(N>1){
    svg.appendChild(sv('path',{class:'area',d:path+' L'+X(N-1).toFixed(1)+' '+base+' L'+X(0).toFixed(1)+' '+base+' Z'}));
    svg.appendChild(sv('path',{class:'ln',d:path}));
  }
  var dense=N>8;
  pts.forEach(function(p,i){
    var x=X(i),y=Y(p.v),last=i===N-1;
    svg.appendChild(sv('circle',{class:'dot'+(last?' last':''),cx:x.toFixed(1),cy:y.toFixed(1),r:last?(mini?4:5):(mini?2.5:3.5)}));
    if(mini)return;
    if(!dense||last||i===0){
      svg.appendChild(sv('text',{class:'vl',x:x.toFixed(1),y:(y<padT+8?y+16:y-8).toFixed(1)},fmt(p.v)));
    }
    if(!dense||i===0||last||i===Math.floor((N-1)/2)){
      svg.appendChild(sv('text',{class:'xl',x:x.toFixed(1),y:H-3},p.label));
    }
  });
  return svg;
}
function spark(vals,W,H){
  var v=vals.filter(function(x){return x!==null});
  var svg=sv('svg',{viewBox:'0 0 '+W+' '+H,class:'spark','aria-hidden':'true'});
  if(!v.length)return svg;
  var lo=Math.min.apply(null,v),hi=Math.max.apply(null,v);
  if(hi===lo){lo-=1;hi+=1}
  var X=function(i){return v.length===1?W/2:3+(W-6)*i/(v.length-1)};
  var Y=function(x){return 3+(H-6)*(1-(x-lo)/(hi-lo))};
  if(v.length>1)svg.appendChild(sv('path',{class:'ln',d:v.map(function(x,i){return (i?'L':'M')+X(i).toFixed(1)+' '+Y(x).toFixed(1)}).join(' ')}));
  v.forEach(function(x,i){var l=i===v.length-1;svg.appendChild(sv('circle',{class:'dot'+(l?' last':''),cx:X(i).toFixed(1),cy:Y(x).toFixed(1),r:l?3:2}))});
  return svg;
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day,size}=ctx;
  const sz=size;
  const n=norm(state);
  const parts=n.settings.parts;
  const recs=sortedRecs(n);
  if(!ui.view)ui.view='main';
  if(!ui.tab)ui.tab='overview';
  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.flat(2).filter(k=>k!==null&&k!==undefined&&k!==false).map(k=>typeof k==='number'?String(k):k));
  const effTarget=r=>{const t=num(r.target);return t!==null?t:n.settings.target};
  const pscore=(r,pid)=>r&&r.scores?num(r.scores[pid]):null;
  const prevPart=(r,pid)=>{for(let i=recs.indexOf(r)-1;i>=0;i--){const v=pscore(recs[i],pid);if(v!==null)return v}return null};
  const delta=(d,label)=>h('span',{class:'dl '+(d>0?'up':d<0?'dn':'eq')},(d>0?'▲ ':d<0?'▼ ':'＝ ')+(d===0?'持平':sgn(d))+(label?' '+label:''));
  const gapChip=(s,tg,short)=>h('span',{class:'gp '+(s>=tg?'ok':'lack')},s>=tg?(short?'已达标 ':'已达目标 ')+sgn(s-tg):(short?'差 ':'距目标还差 ')+fmt(tg-s));
  const go=(view,extra)=>{ui.view=view;if(extra)Object.assign(ui,extra);redraw()};
  const toMain=extra=>Object.assign({view:'main',tab:ui.tab||'overview',draft:null,sd:null,sel:null,err:'',saving:false,confirmDel:false,showAll:!!ui.showAll},extra||{});
  const btn=(label,cls,fn)=>h('button',{type:'button',class:'btn '+(cls||''),onclick:fn},label);
  const emptyState=(title,text,withBtn)=>h('div',{class:'empty'},h('div',{class:'et'},title),h('div',{class:'ex'},text),withBtn?btn('记录第一次成绩','primary',()=>openForm(null)):null);

  function mainView(){
    const wide=sz==='6x3'||sz==='6x6';
    const tabs=[['overview','趋势'],['parts','各部分'],['list','记录']];
    const tabBar=h('div',{class:'tabs',role:'tablist'},tabs.map(t=>h('button',{type:'button',class:'tab'+(ui.tab===t[0]?' on':''),role:'tab','aria-selected':ui.tab===t[0]?'true':'false',onclick:()=>{ui.tab=t[0];redraw()}},t[1])));
    const content=ui.tab==='parts'?partsTab():ui.tab==='list'?listTab():overviewTab();
    return h('div',{class:'view main'},
      wide?h('div',{class:'top'},h('div',{class:'ttl'},'模考成绩'),tabBar):tabBar,
      h('div',{class:'body'},content),
      h('div',{class:'bar'},btn(sz==='3x3'?'＋ 记录':'＋ 记录成绩','primary grow',()=>openForm(null)),btn('设置','',openSettings)));
  }

  function overviewTab(){
    if(!recs.length)return emptyState('还没有模考成绩','填入日期、总分和各部分分数就能开始；只有一次成绩也可以先查看。',true);
    const last=recs[recs.length-1],prev=recs.length>1?recs[recs.length-2]:null;
    const t=num(last.total),tg=effTarget(last);
    const cfg=SZ[sz]||SZ['3x3'];
    const shown=recs.slice(-(ui.showAll?recs.length:cfg.n));
    const mini=!!cfg.mini;
    const sum=h('div',{class:'sum'},
      h('div',{class:'lbl'},'最近一次 · '+shortDate(last.date)+(recs.length>1?' · 共 '+recs.length+' 次':'')),
      h('div',{class:'sumrow'},
        h('div',{class:'big'},fmt(t)),
        h('div',{class:'chips'},
          prev?delta(rd(t-num(prev.total)),'较上次'):h('span',{class:'hint'},'目前仅 1 次成绩'),
          tg!==null?gapChip(t,tg,sz==='3x3'):h('span',{class:'hint'},'未设目标分'))));
    const toggle=recs.length>cfg.n&&!mini?btn(ui.showAll?'看最近 '+cfg.n+' 次':'看全部 '+recs.length+' 次','mini',()=>{ui.showAll=!ui.showAll;redraw()}):null;
    const legend=mini?h('div',{class:'lg'},h('span',{class:'k a'},'最近 '+shown.length+' 次'),tg!==null?h('span',{class:'k t'},'目标 '+fmt(tg)):null):
      h('div',{class:'lg'},h('span',{class:'k a'},'总分'),tg!==null?h('span',{class:'k t'},'目标 '+fmt(tg)):null,h('span',{class:'sp'}),toggle);
    const chart=h('div',{class:'chartbox'},legend,lineChart(shown.map(r=>({label:shortDate(r.date),v:num(r.total)})),tg,cfg.cw,cfg.ch,mini),
      recs.length===1&&!mini?h('div',{class:'hint'},'只有 1 次成绩，再记一次就能看到变化趋势。'):null);
    const tv=shown.map(r=>num(r.total));
    const stats=recs.length>1&&(sz==='3x6'||sz==='6x6')?h('div',{class:'stats'},
      h('div',{},h('span',{class:'sl'},'最高'),h('b',{},fmt(Math.max.apply(null,tv)))),
      h('div',{},h('span',{class:'sl'},'平均'),h('b',{},fmt(tv.reduce((a,b)=>a+b,0)/tv.length))),
      h('div',{},h('span',{class:'sl'},'最低'),h('b',{},fmt(Math.min.apply(null,tv))))):null;
    const extra=sz==='3x6'?h('div',{class:'sec'},h('div',{class:'sh'},'最近记录'),h('div',{class:'list'},recs.slice(-3).reverse().map(r=>recRow(r)))):
      sz==='6x6'&&parts.length?h('div',{class:'sec'},h('div',{class:'sh'},'各部分表现（最近一次）'),partRows({spark:true})):null;
    return h('div',{class:'ov'},sum,chart,stats,extra);
  }


  function partsTab(){
    if(!recs.length)return emptyState('还没有模考成绩','先记录一次成绩，这里会按各部分比较得分与目标。',true);
    if(!parts.length)return h('div',{class:'empty'},h('div',{class:'et'},'还没有设置考试部分'),h('div',{class:'ex'},'在「设置」里添加各部分（如听力、阅读）和各自目标，记录时就能分项填写并比较。'),btn('去设置','primary',openSettings));
    return h('div',{class:'sec'},
      recs.length===1?h('div',{class:'hint'},'目前只有 1 次成绩，暂无上次对比；再记一次就会显示各部分的升降。'):h('div',{class:'hint'},'以最近一次（'+shortDate(recs[recs.length-1].date)+'）为准，升降对比各部分上一次分数。'),
      partRows({spark:sz==='6x3'||sz==='6x6'}));
  }

  function partRows(opts){
    const last=recs[recs.length-1];
    const metrics=parts.map(p=>{
      const s=pscore(last,p.id),tgt=num(p.target),full=num(p.full);
      if(s===null)return null;
      return tgt>0?s/tgt:full>0?s/full:null;
